{"cards": [{"node_code": "N_df0abf0ed8694e10", "definition": "指公路沿线排水、防护、安全及辅助设施的维护与修复，涵盖边沟、涵洞、挡土墙、护栏、标志标线及照明等附属构筑物的技术管理。", "boundary": "本节点聚焦于“附属”与“辅助”设施，区别于路基、路面等主体承载结构。边界在于区分“附属构筑物”与“主体道路”（路基路面归入对应节点）；区分“路线设施”与“交通控制设施”（信号灯、监控等电子设施归入交通工程，本节点侧重物理附属结构）。若涵洞涉及独立桥梁结构，需视具体结构形态判断。", "includes": ["排水系统（边沟、截水沟、涵洞）的疏通、修复与防渗处理", "防护工程（挡土墙、护坡、护脚）的加固、修补与稳定性维护", "安全设施（护栏、隔离栅、标志、标线、反光道钉）的更换、校正与养护"], "excludes": ["路基、路面主体结构的病害处理与修复", "交通信号灯、监控摄像头等电子控制设施的维护", "独立的大型桥梁或隧道主体结构工程"], "sibling_distinctions": [{"other_code": "N_7407182329ad8319", "rule": "区分依据为结构部位：本节点侧重排水、防护等附属结构；路基养护侧重路基土体、边坡及地基的稳定性维护。"}, {"other_code": "N_ef93c656ab901f8a", "rule": "区分依据为结构部位：本节点侧重沿线辅助设施；路面养护侧重行车道、路肩等铺装层的平整度、强度及表面病害修复。"}], "cross_boundary_rule": "若内容涉及涵洞，若为道路排水用小型涵洞归本节点；若为跨越河流等独立桥梁结构，主挂载桥涵工程节点。"}, {"node_code": "N_4b938f4fd0b1a5a3", "definition": "指对既有公路进行技术状况改善、等级提升或线形优化的工程，涵盖路面加铺、路基拓宽、平纵线形调整及结构层改造等综合性改建技术。", "boundary": "本节点聚焦于“改造”与“改建”，即对既有道路进行结构性或功能性提升，区别于日常修补。边界在于区分“局部修补”（归入路基/路面养护）与“整体改造”（涉及线形、等级或结构根本性改变）；区分“改建”与“新建”（利用既有路线基础归本节点，全新选线归道路工程新建部分）。", "includes": ["既有公路路面加铺、翻修及结构层改造技术", "路基拓宽、边坡加固及平纵线形优化工程", "旧路改建的设计原则、施工技术及质量验收标准"], "excludes": ["日常性的局部坑槽修补、裂缝灌缝等预防性养护", "全新公路的选线、勘测及新建施工", "交通信号、监控等电子设施的升级"], "sibling_distinctions": [{"other_code": "N_7407182329ad8319", "rule": "区分依据为工程规模与性质：本节点侧重结构性改造与等级提升；路基养护侧重维持既有路基稳定性的日常维护与局部修复。"}, {"other_code": "N_ef93c656ab901f8a", "rule": "区分依据为工程规模与性质：本节点侧重整体路面结构改造或加铺；路面养护侧重维持既有路面性能的修补与预防性养护。"}], "cross_boundary_rule": "若内容涉及“大修”，若仅涉及结构层翻修且无线形/等级变更，可归入路面/路基养护；若涉及拓宽、改线或等级提升，主挂载本节点。"}, {"node_code": "N_3a283eb168b247cf", "definition": "指公路沿线绿化植被的种植、养护及管理，以及路侧地带（含路肩、边坡、隔离带）的环境整治、水土保持与景观维护技术。", "boundary": "本节点聚焦于“绿化”与“路侧环境”，区别于道路主体结构与附属构筑物。边界在于区分“道路绿化”与“城市园林”（侧重公路沿线生态与景观，非城市公园）；区分“路侧地带”与“路基防护”（本节点侧重植被与环境，路基防护侧重工程结构如挡土墙）。", "includes": ["公路沿线乔木、灌木、草皮的种植、修剪、灌溉及病虫害防治", "路侧边坡、隔离带、中央分隔带的植被恢复与水土保持措施", "路侧环境景观维护、废弃物清理及路域生态管理"], "excludes": ["路基、路面等道路主体结构的工程养护", "挡土墙、护坡等工程性防护设施的维护", "城市公园、广场等非公路区域的园林绿化"], "sibling_distinctions": [{"other_code": "N_df0abf0ed8694e10", "rule": "区分依据为对象性质：本节点侧重生物性植被与环境景观；附属构筑物养护侧重排水、防护等工程性物理设施。"}, {"other_code": "N_7407182329ad8319", "rule": "区分依据为功能侧重：本节点侧重生态景观与路侧环境；路基养护侧重路基土体稳定性及边坡工程防护。"}], "cross_boundary_rule": "若内容涉及边坡绿化，若侧重植被种植与生态恢复归本节点；若侧重边坡工程结构稳定性（如喷锚、挡墙）归路基养护或附属构筑物节点。"}]}
